def _step3(cur):
    cur.execute("""CREATE TABLE rates (src TEXT NOT NULL, dst TEXT NOT NULL, on_date TEXT NOT NULL,
                   rate_text TEXT NOT NULL, PRIMARY KEY (src, dst, on_date))""")
    cur.execute("ALTER TABLE accounts ADD COLUMN closed TEXT")
    for path, c in cur.execute("SELECT path, currency FROM accounts").fetchall():
        if c is None:
            continue
        clean = str(c).strip(" \t\r\n").upper()
        if clean == "":
            cur.execute("UPDATE accounts SET currency = NULL WHERE path = ?", (path,))
        elif not re.fullmatch(r"[A-Z]{3}", clean):
            raise ValueError("account %s has an invalid currency %r" % (path, c))
        elif clean != c:
            cur.execute("UPDATE accounts SET currency = ? WHERE path = ?", (clean, path))
    for pid, c in cur.execute("SELECT id, currency FROM postings").fetchall():
        clean = ("" if c is None else str(c)).strip(" \t\r\n").upper()
        if not re.fullmatch(r"[A-Z]{3}", clean):
            raise ValueError("posting %d has an invalid currency %r" % (pid, c))
        if clean != c:
            cur.execute("UPDATE postings SET currency = ? WHERE id = ?", (clean, pid))


_V4 = [
    """CREATE TABLE budgets (pattern TEXT NOT NULL, period_kind TEXT NOT NULL, minor INTEGER NOT NULL,
       currency TEXT NOT NULL, start_date TEXT NOT NULL, PRIMARY KEY (pattern, period_kind))""",
    """CREATE TABLE recurring (name TEXT PRIMARY KEY, schedule TEXT NOT NULL, template TEXT NOT NULL,
       start_date TEXT NOT NULL, end_date TEXT, max_count INTEGER, materialized_through TEXT)""",
    "CREATE TABLE rules (id INTEGER PRIMARY KEY CHECK (id = 1), body TEXT NOT NULL)",
    "CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    """CREATE TABLE import_keys (key TEXT PRIMARY KEY,
       tx_id INTEGER NOT NULL REFERENCES transactions(id) ON DELETE CASCADE)""",
]


def _run_all(statements):
    def step(cur):
        for s in statements:
            cur.execute(s)
    return step


MIGRATIONS = {1: _run_all(_V1), 2: _step2, 3: _step3, 4: _run_all(_V4)}

_PROFILE_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


@dataclass
class BulkAdd:
    added: List[Transaction] = field(default_factory=list)
    skipped: List[int] = field(default_factory=list)


@dataclass
class ImportOutcome:
    added: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: list = field(default_factory=list)


def _d(text):
    return None if text is None else parse_date(text)


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


def _db_error(e):
    msg = str(e)
    if "locked" in msg or "busy" in msg:
        return ConflictError("the book is busy: %s" % msg)
    return ConflictError("database error: %s" % msg)


def template_to_json(tx):
    return json.dumps({
        "date": None if tx.date is None else format_date(tx.date),
        "payee": tx.payee, "narration": tx.narration, "flag": tx.flag, "id": tx.id,
        "tags": list(tx.tags),
        "postings": [{"account": p.account,
                      "amount": None if p.amount is None else [p.amount.minor, p.amount.currency],
                      "note": p.note} for p in tx.postings],
    }, sort_keys=True, ensure_ascii=False)


def template_from_json(text):
    o = json.loads(text)
    postings = [Posting(p["account"], None if p["amount"] is None else Money(p["amount"][0], p["amount"][1]),
                        p["note"]) for p in o["postings"]]
    return Transaction(_d(o["date"]), o["payee"], o["narration"], postings, tuple(o["tags"]), o["flag"], o["id"])


class Store:
    def __init__(self, conn, path):
        self._conn = conn
        self._path = path
        self._closed = False

    # -- opening ------------------------------------------------------------
    @classmethod
    def open(cls, path, create=False):
        spath = os.fspath(path)
        if os.path.isdir(spath):
            raise ConflictError("%s is a directory, not a book" % spath)
        exists = os.path.exists(spath)
        if not exists:
            if not create:
                raise NotFoundError("no such database: %s" % spath)
            parent = os.path.dirname(os.path.abspath(spath))
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % parent)
        else:
            try:
                with open(spath, "rb") as f:
                    head = f.read(16)
            except OSError as e:
                raise ConflictError("cannot read %s: %s" % (spath, e)) from None
            if head and head != b"SQLite format 3\x00":
                raise ConflictError("%s is not a tallybook database" % spath)
        try:
            conn = sqlite3.connect(spath, timeout=5.0, isolation_level=None, check_same_thread=False)
            conn.execute("PRAGMA foreign_keys = ON")
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            ntables = conn.execute("SELECT COUNT(*) FROM sqlite_master WHERE type = 'table'").fetchone()[0]
        except sqlite3.DatabaseError as e:
            try:
                conn.close()
            except Exception:
                pass
            if not exists:
                raise _db_error(e) from None
            raise ConflictError("%s is not a tallybook database" % spath) from None
        if version == 0 and ntables:
            conn.close()
            raise ConflictError("%s is not a tallybook database" % spath)
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError("%s is at version %d, newer than this tallybook (%d)" % (spath, version,
                                                                                      LATEST_VERSION))
        store = cls(conn, path)
        if create and version == 0:
            try:
                store.migrate()
            except BaseException:
                store.close()
                raise
        return store

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        if not self._closed:
            self._closed = True
            try:
                self._conn.close()
            except Exception:
                pass

    def _alive(self):
        if self._closed:
            raise ConflictError("the book is closed")

    @property
    def version(self):
        self._alive()
        try:
            return self._conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.DatabaseError as e:
            raise _db_error(e) from None

    def _ready(self):
        v = self.version
        if v < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)

    def migrate(self):
        self._alive()
        applied = []
        while True:
            v = self.version
            if v >= LATEST_VERSION:
                return applied
            target = v + 1
            cur = self._conn.cursor()
            try:
                cur.execute("BEGIN IMMEDIATE")
            except sqlite3.DatabaseError as e:
                raise _db_error(e) from None
            try:
                MIGRATIONS[target](cur)
                cur.execute("PRAGMA user_version = %d" % target)
                cur.execute("COMMIT")
            except Exception as e:
                try:
                    cur.execute("ROLLBACK")
                except sqlite3.DatabaseError:
                    pass
                raise ConflictError("migration to version %d failed: %s" % (target, e)) from None
            applied.append(target)

    # -- plumbing -----------------------------------------------------------
    def _read(self, sql, args=()):
        self._ready()
        try:
            return self._conn.execute(sql, args).fetchall()
        except sqlite3.DatabaseError as e:
            raise _db_error(e) from None

    def _write(self, fn):
        """Run fn(cursor) in one immediate transaction; all or nothing."""
        self._ready()
        cur = self._conn.cursor()
        try:
            cur.execute("BEGIN IMMEDIATE")
        except sqlite3.DatabaseError as e:
            raise _db_error(e) from None
        try:
            result = fn(cur)
            cur.execute("COMMIT")
            return result
        except BaseException as e:
            try:
                cur.execute("ROLLBACK")
            except sqlite3.DatabaseError:
                pass
            if isinstance(e, sqlite3.DatabaseError):
                raise _db_error(e) from None
            raise

    # -- accounts -----------------------------------------------------------
    @staticmethod
    def _row_account(r):
        return Account(r[0], r[1], r[2], _d(r[3]), _d(r[5]), r[4])

    def _account_rows(self):
        return self._read("SELECT path, type, currency, opened, note, closed FROM accounts")

    def _all_accounts(self):
        accts = [self._row_account(r) for r in self._account_rows()]
        accts.sort(key=lambda a: a.path.split(":"))
        return accts

    def chart(self):
        chart = Chart()
        for a in self._all_accounts():
            acct = chart.add(a.path, None, a.currency, a.opened, a.note)
            acct.closed = a.closed
        return chart

    def add_account(self, path, type=None, currency=None, opened=None, note=""):
        chart = self.chart()
        acct = chart.add(path, type, currency, opened, note)

        def fn(cur):
            cur.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) VALUES (?, ?, ?, ?, ?, NULL)",
                        (acct.path, acct.type, acct.currency, None if opened is None else format_date(opened),
                         acct.note))
        self._write(fn)
        return Account(acct.path, acct.type, acct.currency, acct.opened, None, acct.note)

    def get_account(self, path):
        rows = self._read("SELECT path, type, currency, opened, note, closed FROM accounts WHERE path = ?",
                          (path if isinstance(path, str) else "",))
        if not rows or not isinstance(path, str):
            raise NotFoundError("no such account: %s" % (path,))
        return self._row_account(rows[0])

    def accounts(self, type=None, under=None, currency=None, include_closed=True):
        if type is not None and type not in TYPES:
            raise ValidationError("invalid account type %r" % (type,))
        out = []
        for a in self._all_accounts():
            if type is not None and a.type != type:
                continue
            if under is not None and not (a.path == under or a.path.startswith(under + ":")):
                continue
            if currency is not None and a.currency != currency:
                continue
            if not include_closed and a.closed is not None:
                continue
            out.append(a)
        return out

    def count_accounts(self, type=None, under=None, currency=None, include_closed=True):
        return len(self.accounts(type, under, currency, include_closed))

    def close_account(self, path, on):
        self.get_account(path)
        chart = self.chart()
        chart.close(path, on)
        last = self._read("SELECT MAX(t.date) FROM postings p JOIN transactions t ON t.id = p.tx_id "
                          "WHERE p.account = ?", (path,))[0][0]
        if last is not None and last > format_date(on):
            raise ConflictError("account %s has postings after %s" % (path, format_date(on)))
        self._write(lambda cur: cur.execute("UPDATE accounts SET closed = ? WHERE path = ?",
                                            (format_date(on), path)))
        return self.get_account(path)

    def set_account_note(self, path, note):
        self.get_account(path)
        if not isinstance(note, str):
            raise ValidationError("note must be text")
        self._write(lambda cur: cur.execute("UPDATE accounts SET note = ? WHERE path = ?", (note, path)))
        return self.get_account(path)

    def delete_account(self, path):
        self.get_account(path)
        n = self._read("SELECT COUNT(*) FROM postings WHERE account = ?", (path,))[0][0]
        if n:
            raise ConflictError("account %s has postings and cannot be deleted" % path)
        self._write(lambda cur: cur.execute("DELETE FROM accounts WHERE path = ?", (path,)))

    # -- transactions -------------------------------------------------------
    def _load_transactions(self, where="", args=()):
        txs = {}
        order = []
        for r in self._read("SELECT id, date, payee, narration, flag FROM transactions %s ORDER BY date, id"
                            % where, args):
            tx = Transaction(_d(r[1]), r[2], r[3], [], (), r[4], r[0])
            txs[r[0]] = tx
            order.append(tx)
        if not txs:
            return order
        if where:
            marks = ",".join("?" * len(txs))
            ids = tuple(txs)
            prow = self._read("SELECT tx_id, account, minor, currency, note FROM postings WHERE tx_id IN (%s) "
                              "ORDER BY tx_id, seq" % marks, ids)
            trow = self._read("SELECT tx_id, tag FROM tags WHERE tx_id IN (%s) ORDER BY tx_id, tag" % marks, ids)
        else:
            prow = self._read("SELECT tx_id, account, minor, currency, note FROM postings ORDER BY tx_id, seq")
            trow = self._read("SELECT tx_id, tag FROM tags ORDER BY tx_id, tag")
        for tx_id, account, minor, cur, note in prow:
            if tx_id in txs:
                txs[tx_id].postings.append(Posting(account, Money(minor, cur), note))
        tags = {}
        for tx_id, tag in trow:
            tags.setdefault(tx_id, []).append(tag)
        for tx_id, tl in tags.items():
            if tx_id in txs:
                txs[tx_id].tags = tuple(sorted(set(tl)))
        return order

    def rate_table(self):
        table = RateTable()
        for src, dst, on, text in self.rate_rows():
            table.set(src, dst, text, on)
        return table

    def ledger(self):
        led = Ledger(self.chart(), self.rate_table())
        for tx in self._load_transactions():
            led._load(tx)
        return led

    def _validator(self):
        return Ledger(self.chart(), self.rate_table())

    @staticmethod
    def _insert(cur, tx):
        cur.execute("INSERT INTO transactions (date, payee, narration, cleared, flag) VALUES (?, ?, ?, ?, ?)",
                    (format_date(tx.date), tx.payee, tx.narration, 1 if tx.flag == "*" else 0, tx.flag))
        tx_id = cur.lastrowid
        for seq, p in enumerate(tx.postings):
            cur.execute("INSERT INTO postings (tx_id, seq, account, minor, currency, note) VALUES (?, ?, ?, ?, ?, ?)",
                        (tx_id, seq, p.account, p.amount.minor, p.amount.currency, p.note))
        for t in tx.tags:
            cur.execute("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", (tx_id, t))
        return Transaction(tx.date, tx.payee, tx.narration, list(tx.postings), tuple(tx.tags), tx.flag, tx_id)

    @staticmethod
    def _strip_id(tx):
        if isinstance(tx, Transaction) and tx.id is not None:
            return Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None)
        return tx

    def add_transaction(self, tx):
        checked = self._validator().add(self._strip_id(tx))
        return self._write(lambda cur: self._insert(cur, checked))

    def _resolve_query(self, query):
        from tallybook.query import Query, parse_query

        if query is None:
            return None
        if isinstance(query, Query):
            return None if query.is_empty else query
        if not isinstance(query, str):
            raise ValidationError("query must be text")
        if query.strip() == "":
            return None
        return parse_query(query, chart=self.chart())

    def transactions(self, query=None, limit=None, offset=0):
        if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
            raise ValidationError("limit must be a whole number of at least 0")
        if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
            raise ValidationError("offset must be a whole number of at least 0")
        q = self._resolve_query(query)
        txs = self._load_transactions()
        if q is not None:
            txs = [t for t in txs if q.matches(t)]
        txs = txs[offset:]
        if limit is not None:
            txs = txs[:limit]
        return txs

    def count_transactions(self, query=None):
        return len(self.transactions(query))

    def has_import_key(self, key):
        return bool(self._read("SELECT 1 FROM import_keys WHERE key = ?", (key,)))

    def get_transaction(self, id):
        if not isinstance(id, int) or isinstance(id, bool):
            raise NotFoundError("no transaction %s" % (id,))
        found = self._load_transactions("WHERE id = ?", (id,))
        if not found:
            raise NotFoundError("no transaction %s" % (id,))
        return found[0]

    def delete_transaction(self, id):
        tx = self.get_transaction(id)

        def fn(cur):
            cur.execute("DELETE FROM import_keys WHERE tx_id = ?", (id,))
            cur.execute("DELETE FROM tags WHERE tx_id = ?", (id,))
            cur.execute("DELETE FROM postings WHERE tx_id = ?", (id,))
            cur.execute("DELETE FROM transactions WHERE id = ?", (id,))
        self._write(fn)
        return tx

    def add_transactions(self, txs, keys=None):
        txs = list(txs)
        if keys is not None:
            keys = list(keys)
            if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
                raise ValidationError("keys must be one text per transaction")
        validator = self._validator()
        existing = set()
        if keys is not None:
            existing = {r[0] for r in self._read("SELECT key FROM import_keys")}
        plan = []
        skipped = []
        seen = set()
        for i, tx in enumerate(txs):
            if keys is not None and (keys[i] in existing or keys[i] in seen):
                skipped.append(i)
                continue
            try:
                checked = validator.add(self._strip_id(tx))
            except TallybookError as e:
                e.detail = {"index": i}
                raise
            if keys is not None:
                seen.add(keys[i])
            plan.append((i, checked))

        def fn(cur):
            out = []
            for i, checked in plan:
                stored = self._insert(cur, checked)
                if keys is not None:
                    cur.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (keys[i], stored.id))
                out.append(stored)
            return out
        return BulkAdd(self._write(fn), skipped)

    # -- rates --------------------------------------------------------------
    def rate_rows(self):
        rows = self._read("SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")
        return [(r[0], r[1], _d(r[2]), r[3]) for r in rows]

    def set_rate(self, src, dst, rate_text, on):
        RateTable().set(src, dst, rate_text, on)
        self._write(lambda cur: cur.execute(
            "INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
            (src, dst, format_date(on), rate_text)))

    def remove_rate(self, src, dst, on):
        key = (src, dst, format_date(on) if _is_date(on) else None)
        if key[2] is None or not self._read("SELECT 1 FROM rates WHERE src = ? AND dst = ? AND on_date = ?", key):
            raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, key[2] if key[2] else on))
        self._write(lambda cur: cur.execute("DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?", key))

    # -- budgets ------------------------------------------------------------
    def budgets(self):
        rows = self._read("SELECT pattern, period_kind, minor, currency, start_date FROM budgets")
        out = [Budget(r[0], r[1], Money(r[2], r[3]), _d(r[4])) for r in rows]
        kinds = {"month": 0, "quarter": 1, "year": 2}
        out.sort(key=lambda b: (b.pattern, kinds.get(b.period_kind, 9)))
        return out

    def add_budget(self, budget):
        if not isinstance(budget, Budget):
            raise ValidationError("not a budget: %r" % (budget,))
        if self._read("SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
                      (budget.pattern, budget.period_kind)):
            raise ConflictError("a budget for %s per %s already exists" % (budget.pattern, budget.period_kind))
        self._write(lambda cur: cur.execute(
            "INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) VALUES (?, ?, ?, ?, ?)",
            (budget.pattern, budget.period_kind, budget.amount.minor, budget.amount.currency,
             format_date(budget.start))))
        return budget

    def remove_budget(self, pattern, period_kind):
        for b in self.budgets():
            if b.pattern == pattern and b.period_kind == period_kind:
                self._write(lambda cur: cur.execute(
                    "DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind)))
                return b
        raise NotFoundError("no budget for %s per %s" % (pattern, period_kind))

    # -- recurring ----------------------------------------------------------
    def _recurring_rows(self):
        from tallybook.recurring import Recurring

        out = []
        for r in self._read("SELECT name, schedule, template, start_date, end_date, max_count, "
                            "materialized_through FROM recurring ORDER BY name"):
            rec = Recurring(r[0], r[1], template_from_json(r[2]), _d(r[3]), _d(r[4]), r[5])
            out.append((rec, _d(r[6])))
        return out

    def recurring(self):
        return [rec for rec, _ in self._recurring_rows()]

    def add_recurring(self, rec):
        from tallybook.recurring import Recurring

        if not isinstance(rec, Recurring):
            raise ValidationError("not a recurring item: %r" % (rec,))
        if self._read("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)):
            raise ConflictError("recurring item %s already exists" % rec.name)
        self._write(lambda cur: cur.execute(
            "INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count, materialized_through)"
            " VALUES (?, ?, ?, ?, ?, ?, NULL)",
            (rec.name, str(rec.schedule), template_to_json(rec.template), format_date(rec.start),
             None if rec.end is None else format_date(rec.end), rec.count)))
        return rec

    def remove_recurring(self, name):
        for rec, _ in self._recurring_rows():
            if rec.name == name:
                self._write(lambda cur: cur.execute("DELETE FROM recurring WHERE name = ?", (name,)))
                return rec
        raise NotFoundError("no recurring item %s" % (name,))

    def materialized_through(self, name):
        for rec, through in self._recurring_rows():
            if rec.name == name:
                return through
        raise NotFoundError("no recurring item %s" % (name,))

    def materialize(self, upto=None, today=None):
        from datetime import timedelta

        from tallybook.recurring import instantiate, occurrences

        for v in (upto, today):
            if v is not None and not _is_date(v):
                raise ValidationError("invalid date %r" % (v,))
        if upto is None and today is None:
            raise ValidationError("materialize needs upto or today")
        horizon = min(d for d in (upto, today) if d is not None)
        items = []
        moves = []
        for rec, through in self._recurring_rows():
            begin = rec.start
            if through is not None:
                try:
                    begin = max(begin, through + timedelta(days=1))
                except OverflowError:
                    continue
            for d in occurrences(rec, begin, horizon):
                items.append((d, rec.name, instantiate(rec, d)))
            if through is None or horizon > through:
                moves.append(rec.name)
        items.sort(key=lambda x: (x[0], x[1]))
        validator = self._validator()
        checked = [validator.add(tx) for _, _, tx in items]

        def fn(cur):
            out = [self._insert(cur, c) for c in checked]
            for name in moves:
                cur.execute("UPDATE recurring SET materialized_through = ? WHERE name = ?",
                            (format_date(horizon), name))
            return out
        return self._write(fn)

    # -- rules and settings -------------------------------------------------
    def rules_text(self):
        rows = self._read("SELECT body FROM rules WHERE id = 1")
        return rows[0][0] if rows else ""

    def rules(self):
        from tallybook.rules import parse_rules
        return parse_rules(self.rules_text())

    def set_rules(self, text):
        from tallybook.rules import parse_rules
        parse_rules(text)
        self._write(lambda cur: cur.execute("INSERT OR REPLACE INTO rules (id, body) VALUES (1, ?)", (text,)))

    def get_setting(self, key, default=None):
        rows = self._read("SELECT value FROM settings WHERE key = ?", (key if isinstance(key, str) else "",))
        return rows[0][0] if rows and isinstance(key, str) else default

    def set_setting(self, key, value):
        if not isinstance(key, str) or not key or not isinstance(value, str):
            raise ValidationError("a setting needs a non-empty text key and a text value")
        self._write(lambda cur: cur.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)",
                                            (key, value)))

    def delete_setting(self, key):
        self._write(lambda cur: cur.execute("DELETE FROM settings WHERE key = ?", (key,)))

    def settings(self):
        return dict(self._read("SELECT key, value FROM settings ORDER BY key"))

    @staticmethod
    def _check_profile_name(name):
        if not isinstance(name, str) or not _PROFILE_RE.fullmatch(name):
            raise ValidationError("invalid profile name %r" % (name,))

    def set_profile(self, name, text):
        from tallybook.csvimport import parse_profile
        self._check_profile_name(name)
        parse_profile(text)
        self.set_setting("profile." + name, text)

    def profile_text(self, name):
        if isinstance(name, str):
            value = self.get_setting("profile." + name)
            if value is not None:
                return value
        raise NotFoundError("no such profile: %s" % (name,))

    def profiles(self):
        return sorted(k[len("profile."):] for k in self.settings() if k.startswith("profile."))

