class Store:
    def __init__(self, conn, path):
        self._conn = conn
        self._path = path
        self._closed = False

    # -- opening ------------------------------------------------------------
    @classmethod
    def open(cls, path, create=False):
        spath = os.fspath(path)
        if os.path.isdir(spath):
            raise ConflictError("%s is a directory, not a book" % spath)
        exists = os.path.exists(spath)
        if not exists:
            if not create:
                raise NotFoundError("no such database: %s" % spath)
            parent = os.path.dirname(os.path.abspath(spath))
            if not os.path.isdir(parent):
                raise NotFoundError("no such directory: %s" % parent)
        else:
            try:
                with open(spath, "rb") as f:
                    head = f.read(16)
            except OSError as e:
                raise ConflictError("cannot read %s: %s" % (spath, e)) from None
            if head and head != b"SQLite format 3\x00":
                raise ConflictError("%s is not a tallybook database" % spath)
        try:
            conn = sqlite3.connect(spath, timeout=5.0, isolation_level=None, check_same_thread=False)
            conn.execute("PRAGMA foreign_keys = ON")
            version = conn.execute("PRAGMA user_version").fetchone()[0]
            ntables = conn.execute("SELECT COUNT(*) FROM sqlite_master WHERE type = 'table'").fetchone()[0]
        except sqlite3.DatabaseError as e:
            try:
                conn.close()
            except Exception:
                pass
            if not exists:
                raise _db_error(e) from None
            raise ConflictError("%s is not a tallybook database" % spath) from None
        if version == 0 and ntables:
            conn.close()
            raise ConflictError("%s is not a tallybook database" % spath)
        if version > LATEST_VERSION:
            conn.close()
            raise ConflictError("%s is at version %d, newer than this tallybook (%d)" % (spath, version,
                                                                                      LATEST_VERSION))
        store = cls(conn, path)
        if create and version == 0:
            try:
                store.migrate()
            except BaseException:
                store.close()
                raise
        return store

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()
        return False

    def close(self):
        if not self._closed:
            self._closed = True
            try:
                self._conn.close()
            except Exception:
                pass

    def _alive(self):
        if self._closed:
            raise ConflictError("the book is closed")

    @property
    def version(self):
        self._alive()
        try:
            return self._conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.DatabaseError as e:
            raise _db_error(e) from None

    def _ready(self):
        v = self.version
        if v < LATEST_VERSION:
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)

    def migrate(self):
        self._alive()
        applied = []
        while True:
            v = self.version
            if v >= LATEST_VERSION:
                return applied
            target = v + 1
            cur = self._conn.cursor()
            try:
                cur.execute("BEGIN IMMEDIATE")
            except sqlite3.DatabaseError as e:
                raise _db_error(e) from None
            try:
                MIGRATIONS[target](cur)
                cur.execute("PRAGMA user_version = %d" % target)
                cur.execute("COMMIT")
            except Exception as e:
                try:
                    cur.execute("ROLLBACK")
                except sqlite3.DatabaseError:
                    pass
                raise ConflictError("migration to version %d failed: %s" % (target, e)) from None
            applied.append(target)

