        if q is not None:
            txs = [t for t in txs if q.matches(t)]
        txs = txs[offset:]
        if limit is not None:
            txs = txs[:limit]
        return txs

    def count_transactions(self, query=None):
        return len(self.transactions(query))

    def has_import_key(self, key):
        return bool(self._read("SELECT 1 FROM import_keys WHERE key = ?", (key,)))

    def get_transaction(self, id):
        if not isinstance(id, int) or isinstance(id, bool):
            raise NotFoundError("no transaction %s" % (id,))
        found = self._load_transactions("WHERE id = ?", (id,))
        if not found:
            raise NotFoundError("no transaction %s" % (id,))
        return found[0]

    def delete_transaction(self, id):
        tx = self.get_transaction(id)

        def fn(cur):
            cur.execute("DELETE FROM import_keys WHERE tx_id = ?", (id,))
            cur.execute("DELETE FROM tags WHERE tx_id = ?", (id,))
            cur.execute("DELETE FROM postings WHERE tx_id = ?", (id,))
            cur.execute("DELETE FROM transactions WHERE id = ?", (id,))
        self._write(fn)
        return tx

    def add_transactions(self, txs, keys=None):
        txs = list(txs)
        if keys is not None:
            keys = list(keys)
            if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
                raise ValidationError("keys must be one text per transaction")
        validator = self._validator()
        existing = set()
        if keys is not None:
            existing = {r[0] for r in self._read("SELECT key FROM import_keys")}
        plan = []
        skipped = []
        seen = set()
        for i, tx in enumerate(txs):
            if keys is not None and (keys[i] in existing or keys[i] in seen):
                skipped.append(i)
                continue
            try:
                checked = validator.add(self._strip_id(tx))
            except TallybookError as e:
                e.detail = {"index": i}
                raise
            if keys is not None:
                seen.add(keys[i])
            plan.append((i, checked))

        def fn(cur):
            out = []
            for i, checked in plan:
                stored = self._insert(cur, checked)
                if keys is not None:
                    cur.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (keys[i], stored.id))
                out.append(stored)
            return out
        return BulkAdd(self._write(fn), skipped)

    # -- rates --------------------------------------------------------------
    def rate_rows(self):
        rows = self._read("SELECT src, dst, on_date, rate_text FROM rates ORDER BY src, dst, on_date")
        return [(r[0], r[1], _d(r[2]), r[3]) for r in rows]

    def set_rate(self, src, dst, rate_text, on):
        RateTable().set(src, dst, rate_text, on)
        self._write(lambda cur: cur.execute(
            "INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
            (src, dst, format_date(on), rate_text)))

    def remove_rate(self, src, dst, on):
        key = (src, dst, format_date(on) if _is_date(on) else None)
        if key[2] is None or not self._read("SELECT 1 FROM rates WHERE src = ? AND dst = ? AND on_date = ?", key):
            raise NotFoundError("no rate %s -> %s set on %s" % (src, dst, key[2] if key[2] else on))
        self._write(lambda cur: cur.execute("DELETE FROM rates WHERE src = ? AND dst = ? AND on_date = ?", key))

    # -- budgets ------------------------------------------------------------
    def budgets(self):
        rows = self._read("SELECT pattern, period_kind, minor, currency, start_date FROM budgets")
        out = [Budget(r[0], r[1], Money(r[2], r[3]), _d(r[4])) for r in rows]
        kinds = {"month": 0, "quarter": 1, "year": 2}
        out.sort(key=lambda b: (b.pattern, kinds.get(b.period_kind, 9)))
        return out

    def add_budget(self, budget):
        if not isinstance(budget, Budget):
            raise ValidationError("not a budget: %r" % (budget,))
        if self._read("SELECT 1 FROM budgets WHERE pattern = ? AND period_kind = ?",
                      (budget.pattern, budget.period_kind)):
            raise ConflictError("a budget for %s per %s already exists" % (budget.pattern, budget.period_kind))
        self._write(lambda cur: cur.execute(
            "INSERT INTO budgets (pattern, period_kind, minor, currency, start_date) VALUES (?, ?, ?, ?, ?)",
            (budget.pattern, budget.period_kind, budget.amount.minor, budget.amount.currency,
             format_date(budget.start))))
        return budget

    def remove_budget(self, pattern, period_kind):
        for b in self.budgets():
            if b.pattern == pattern and b.period_kind == period_kind:
                self._write(lambda cur: cur.execute(
                    "DELETE FROM budgets WHERE pattern = ? AND period_kind = ?", (pattern, period_kind)))
                return b
        raise NotFoundError("no budget for %s per %s" % (pattern, period_kind))

    # -- recurring ----------------------------------------------------------
    def _recurring_rows(self):
        from tallybook.recurring import Recurring

        out = []
        for r in self._read("SELECT name, schedule, template, start_date, end_date, max_count, "
                            "materialized_through FROM recurring ORDER BY name"):
            rec = Recurring(r[0], r[1], template_from_json(r[2]), _d(r[3]), _d(r[4]), r[5])
            out.append((rec, _d(r[6])))
        return out

    def recurring(self):
        return [rec for rec, _ in self._recurring_rows()]

    def add_recurring(self, rec):
        from tallybook.recurring import Recurring

        if not isinstance(rec, Recurring):
            raise ValidationError("not a recurring item: %r" % (rec,))
        if self._read("SELECT 1 FROM recurring WHERE name = ?", (rec.name,)):
            raise ConflictError("recurring item %s already exists" % rec.name)
        self._write(lambda cur: cur.execute(
            "INSERT INTO recurring (name, schedule, template, start_date, end_date, max_count, materialized_through)"
            " VALUES (?, ?, ?, ?, ?, ?, NULL)",
            (rec.name, str(rec.schedule), template_to_json(rec.template), format_date(rec.start),
             None if rec.end is None else format_date(rec.end), rec.count)))
        return rec

    def remove_recurring(self, name):
        for rec, _ in self._recurring_rows():
            if rec.name == name:
                self._write(lambda cur: cur.execute("DELETE FROM recurring WHERE name = ?", (name,)))
                return rec
        raise NotFoundError("no recurring item %s" % (name,))

    def materialized_through(self, name):
        for rec, through in self._recurring_rows():
            if rec.name == name:
                return through
        raise NotFoundError("no recurring item %s" % (name,))

    def materialize(self, upto=None, today=None):
        from datetime import timedelta

        from tallybook.recurring import instantiate, occurrences

        for v in (upto, today):
            if v is not None and not _is_date(v):
                raise ValidationError("invalid date %r" % (v,))
        if upto is None and today is None:
            raise ValidationError("materialize needs upto or today")
        horizon = min(d for d in (upto, today) if d is not None)
        items = []
        moves = []
        for rec, through in self._recurring_rows():
            begin = rec.start
            if through is not None:
                try:
                    begin = max(begin, through + timedelta(days=1))
                except OverflowError:
                    continue
            for d in occurrences(rec, begin, horizon):
                items.append((d, rec.name, instantiate(rec, d)))
            if through is None or horizon > through:
                moves.append(rec.name)
        items.sort(key=lambda x: (x[0], x[1]))
        validator = self._validator()
        checked = [validator.add(tx) for _, _, tx in items]

        def fn(cur):
            out = [self._insert(cur, c) for c in checked]
            for name in moves:
                cur.execute("UPDATE recurring SET materialized_through = ? WHERE name = ?",
                            (format_date(horizon), name))
            return out
        return self._write(fn)

    # -- rules and settings -------------------------------------------------
    def rules_text(self):
        rows = self._read("SELECT body FROM rules WHERE id = 1")
        return rows[0][0] if rows else ""

    def rules(self):
        from tallybook.rules import parse_rules
        return parse_rules(self.rules_text())

    def set_rules(self, text):
        from tallybook.rules import parse_rules
        parse_rules(text)
        self._write(lambda cur: cur.execute("INSERT OR REPLACE INTO rules (id, body) VALUES (1, ?)", (text,)))

    def get_setting(self, key, default=None):
        rows = self._read("SELECT value FROM settings WHERE key = ?", (key if isinstance(key, str) else "",))
        return rows[0][0] if rows and isinstance(key, str) else default

    def set_setting(self, key, value):
        if not isinstance(key, str) or not key or not isinstance(value, str):
            raise ValidationError("a setting needs a non-empty text key and a text value")
        self._write(lambda cur: cur.execute("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)",
                                            (key, value)))

    def delete_setting(self, key):
        self._write(lambda cur: cur.execute("DELETE FROM settings WHERE key = ?", (key,)))

    def settings(self):
        return dict(self._read("SELECT key, value FROM settings ORDER BY key"))

    @staticmethod
    def _check_profile_name(name):
        if not isinstance(name, str) or not _PROFILE_RE.fullmatch(name):
            raise ValidationError("invalid profile name %r" % (name,))

    def set_profile(self, name, text):
        from tallybook.csvimport import parse_profile
        self._check_profile_name(name)
        parse_profile(text)
        self.set_setting("profile." + name, text)

    def profile_text(self, name):
        if isinstance(name, str):
            value = self.get_setting("profile." + name)
            if value is not None:
                return value
        raise NotFoundError("no such profile: %s" % (name,))

    def profiles(self):
        return sorted(k[len("profile."):] for k in self.settings() if k.startswith("profile."))

    def remove_profile(self, name):
        self.profile_text(name)
        self.delete_setting("profile." + name)

    # -- import -------------------------------------------------------------
    def import_csv(self, text, profile, apply_rules=True):
        from tallybook.csvimport import ImportProfile, import_csv, parse_profile

        if isinstance(profile, ImportProfile):
            prof = profile
        elif isinstance(profile, str) and _PROFILE_RE.fullmatch(profile):
            prof = parse_profile(self.profile_text(profile))
        else:
            prof = parse_profile(profile)
        rules = self.rules() if apply_rules else None
        result = import_csv(text, prof, rules, self._load_transactions())
        if result.errors:
            return ImportOutcome([], list(result.duplicates), list(result.errors))
        counts = {}
        new, keys = [], []
        for tx, dup in result.ordered:
            p = tx.postings[0]
            base = "%s|%s|%s|%d %s" % (format_date(tx.date), tx.payee, p.account, p.amount.minor, p.amount.currency)
            counts[base] = counts.get(base, 0) + 1
            if not dup:
                new.append(tx)
                keys.append("%s|%d" % (base, counts[base]))
        bulk = self.add_transactions(new, keys)
        dups = list(result.duplicates) + [new[i] for i in bulk.skipped]
        return ImportOutcome(bulk.added, dups, [])

    # -- journals -----------------------------------------------------------
    def journal(self):
        accts = self.accounts()
        txs = []
        for t in self._load_transactions():
            t.id = None
            txs.append(t)
        return Journal(accts, self.rate_rows(), txs)

    def load_journal(self, journal):
        chart = self.chart()
        for a in journal.accounts:
            chart.add(a.path, a.type, a.currency, a.opened, a.note)
            if a.closed is not None:
                chart.close(a.path, a.closed)
        rates = self.rate_table()
        for src, dst, on, text in journal.rates:
            rates.set(src, dst, text, on)
        validator = Ledger(chart, rates)
        checked = [validator.add(self._strip_id(tx)) for tx in journal.transactions]

        def fn(cur):
            for a in journal.accounts:
                cur.execute("INSERT INTO accounts (path, type, currency, opened, note, closed) VALUES (?, ?, ?, ?, ?, ?)",
                            (a.path, chart.get(a.path).type, a.currency,
                             None if a.opened is None else format_date(a.opened), a.note,
                             None if a.closed is None else format_date(a.closed)))
            for src, dst, on, text in journal.rates:
                cur.execute("INSERT OR REPLACE INTO rates (src, dst, on_date, rate_text) VALUES (?, ?, ?, ?)",
                            (src, dst, format_date(on), text))
            return [self._insert(cur, c) for c in checked]
        return self._write(fn)

    # -- health -------------------------------------------------------------
    def check(self):
        problems = []
        try:
            for (msg,) in self._read("PRAGMA integrity_check"):
                if msg != "ok":
                    problems.append("integrity check: %s" % msg)
        except ConflictError as e:
            problems.append("integrity check: %s" % e.message)
        for (pid, tx_id) in self._read("SELECT id, tx_id FROM postings WHERE tx_id NOT IN (SELECT id FROM transactions)"):
            problems.append("posting %d points to missing transaction %d" % (pid, tx_id))
        for (tx_id, tag) in self._read("SELECT tx_id, tag FROM tags WHERE tx_id NOT IN (SELECT id FROM transactions)"):
            problems.append("tag %s points to missing transaction %d" % (tag, tx_id))
        for (key, tx_id) in self._read("SELECT key, tx_id FROM import_keys WHERE tx_id NOT IN (SELECT id FROM transactions)"):
            problems.append("import key %s points to missing transaction %d" % (key, tx_id))
        for (tx_id,) in self._read("SELECT id FROM transactions WHERE id NOT IN (SELECT tx_id FROM postings)"):
            problems.append("transaction %d has no postings" % tx_id)
        for (pid, tx_id, acct) in self._read("SELECT id, tx_id, account FROM postings "
                                             "WHERE account NOT IN (SELECT path FROM accounts)"):
            problems.append("posting %d of transaction %d is on unknown account %s" % (pid, tx_id, acct))
        for (tx_id, cur, total) in self._read("SELECT tx_id, currency, SUM(minor) FROM postings "
                                              "WHERE tx_id IN (SELECT id FROM transactions) "
                                              "GROUP BY tx_id, currency HAVING SUM(minor) != 0"):
            problems.append("transaction %d does not balance in %s (off by %d minor units)" % (tx_id, cur, total))
        return sorted(problems)

    def backup(self, dest):
        self._ready()
        d = os.fspath(dest)
        if os.path.exists(d):
            raise ConflictError("%s already exists" % d)
        parent = os.path.dirname(os.path.abspath(d))
        if not os.path.isdir(parent):
            raise NotFoundError("no such directory: %s" % parent)
        try:
            target = sqlite3.connect(d)
            try:
                self._conn.backup(target)
            finally:
                target.close()
        except sqlite3.DatabaseError as e:
            raise _db_error(e) from None

    def info(self):
        count = lambda t: self._read("SELECT COUNT(*) FROM %s" % t)[0][0]
        return {
            "path": self._path if isinstance(self._path, str) else os.fspath(self._path),
            "version": self.version,
            "accounts": count("accounts"),
            "transactions": count("transactions"),
            "postings": count("postings"),
            "rates": count("rates"),
            "budgets": count("budgets"),
            "recurring": count("recurring"),
        }
