"""A small command-line parser with tallybook's exact rules."""


class UsageError(Exception):
    """A command line that is itself wrong (exit status 2)."""


class HelpRequested(Exception):
    def __init__(self, text):
        super().__init__(text)
        self.text = text


class Spec:
    def __init__(self, words, positionals=(), options=None, required=(), usage="", summary=""):
        self.words = tuple(words)
        self.positionals = list(positionals)  # (name, arity) arity: '1', '?', '+'
        self.options = dict(options or {})    # '--name' -> 'v' value, 'f' flag, 'm' repeated value
        self.required = tuple(required)
        self.usage = usage
        self.summary = summary

    def usage_text(self):
        return "usage: tallybook %s\n" % self.usage


def parse_command_args(spec, args):
    opts = {}
    pos = []
    i = 0
    only_pos = False
    while i < len(args):
        a = args[i]
        i += 1
        if only_pos:
            pos.append(a)
            continue
        if a == "--":
            only_pos = True
            continue
        if a in ("-h", "--help"):
            raise HelpRequested(spec.usage_text())
        if a == "-p" and "--posting" in spec.options:
            name, has_eq, val = "--posting", False, None
        elif a.startswith("--"):
            name, eq, val = a.partition("=")
            has_eq = bool(eq)
        else:
            pos.append(a)
            continue
        kind = spec.options.get(name)
        if kind is None:
            raise UsageError("unknown option %s" % name)
        if kind == "f":
            if has_eq:
                raise UsageError("option %s takes no value" % name)
            if name in opts:
                raise UsageError("option %s given twice" % name)
            opts[name] = True
            continue
        if not has_eq:
            if i >= len(args):
                raise UsageError("option %s needs a value" % name)
            val = args[i]
            i += 1
        if kind == "m":
            opts.setdefault(name, []).append(val)
        else:
            if name in opts:
                raise UsageError("option %s given twice" % name)
            opts[name] = val
    for r in spec.required:
        if r not in opts:
            raise UsageError("missing required option %s" % r)
    # positionals
    required = sum(1 for _, ar in spec.positionals if ar in ("1", "+"))
    optional = sum(1 for _, ar in spec.positionals if ar == "?")
    variadic = any(ar == "+" for _, ar in spec.positionals)
    if len(pos) < required:
        missing = [n for n, ar in spec.positionals if ar in ("1", "+")][len(pos):] or ["argument"]
        raise UsageError("missing argument %s" % missing[0])
    if not variadic and len(pos) > required + optional:
        raise UsageError("unexpected argument %r" % pos[required + optional])
    values = {}
    extra_opt = len(pos) - required
    k = 0
    for name, ar in spec.positionals:
        if ar == "1":
            values[name] = pos[k]
            k += 1
        elif ar == "?":
            if extra_opt > 0:
                values[name] = pos[k]
                k += 1
                extra_opt -= 1
            else:
                values[name] = None
        else:
            values[name] = pos[k:]
            k = len(pos)
    return values, opts
