"""The small JSON-over-HTTP API on a book file."""

import json
import signal
import sys
import threading
from datetime import date
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote

from tallybook import __version__
from tallybook.errors import ParseError, TallybookError, ValidationError

MAX_BODY = 1048576
_MAX_INT = 9223372036854775807
_REPORTS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


class HttpError(Exception):
    def __init__(self, status, message, headers=None):
        super().__init__(message)
        self.status = status
        self.message = message
        self.headers = headers or {}


# -- routing -----------------------------------------------------------------------

def route(pieces):
    """Return (name, params, verbs) for a path, or None."""
    n = len(pieces)
    if any(p == "" for p in pieces):
        return None
    head = pieces[0] if pieces else None
    if n == 1:
        table = {
            "health": ("GET",), "accounts": ("GET", "POST"), "transactions": ("GET", "POST"),
            "rates": ("DELETE", "GET", "PUT"), "budgets": ("DELETE", "GET", "POST"),
            "recurring": ("DELETE", "GET", "POST"), "rules": ("GET", "PUT"), "export": ("GET",),
            "import": ("POST",),
        }
        if head in table:
            return head, {}, table[head]
        return None
    if n == 2:
        if head == "accounts":
            return "account", {"path": pieces[1]}, ("GET",)
        if head == "transactions":
            if pieces[1].isdigit() and pieces[1].isascii():
                return "transaction", {"id": int(pieces[1])}, ("DELETE", "GET")
            return None
        if head == "budgets" and pieces[1] == "status":
            return "budget_status", {}, ("GET",)
        if head == "recurring" and pieces[1] == "materialize":
            return "materialize", {}, ("POST",)
        if head == "reports" and pieces[1] in _REPORTS:
            return "report", {"name": pieces[1]}, ("GET",)
        return None
    if n == 3 and head == "accounts" and pieces[2] == "close":
        return "close", {"path": pieces[1]}, ("POST",)
    return None


# -- request values ----------------------------------------------------------------

_MISSING = object()


def get_fields(body, spec, where=""):
    """spec: name -> (kind, required). Returns dict of given (non-null) fields."""
    if not isinstance(body, dict):
        raise ValidationError("%sexpected a JSON object" % where)
    for k in body:
        if k not in spec:
            raise ValidationError("unknown field: %s%s" % (where, k))
    out = {}
    for name, (kind, required) in spec.items():
        v = body.get(name, None)
        if v is None:
            if required:
                raise ValidationError("missing field: %s%s" % (where, name))
            continue
        if kind == "str" and not isinstance(v, str):
            raise ValidationError("field %s%s must be text" % (where, name))
        if kind == "bool" and not isinstance(v, bool):
            raise ValidationError("field %s%s must be true or false" % (where, name))
        if kind == "list" and not isinstance(v, list):
            raise ValidationError("field %s%s must be a list" % (where, name))
        if kind == "obj" and not isinstance(v, dict):
            raise ValidationError("field %s%s must be an object" % (where, name))
        if kind == "money" and not isinstance(v, (str, dict)):
            raise ValidationError("field %s%s must be money" % (where, name))
        out[name] = v
    return out


def to_money(v, where="amount"):
    from tallybook.money import Money
    if isinstance(v, str):
        return Money.parse(v)
    if isinstance(v, dict):
        if set(v) != {"amount", "currency"} or not isinstance(v["amount"], str) or not isinstance(v["currency"], str):
            raise ValidationError("%s must be {\"amount\": text, \"currency\": text} or \"AMOUNT CUR\"" % where)
        return Money.of(v["amount"], v["currency"])
    raise ValidationError("%s must be money" % where)


def to_date(text):
    from tallybook.dates import parse_date
    return parse_date(text)


def qbool(q, name, default):
    if name not in q:
        return default
    v = q[name].lower()
    if v in ("true", "yes", "1"):
        return True
    if v in ("false", "no", "0"):
        return False
    raise ValidationError("parameter %s must be yes or no" % name)


def qint(q, name):
    if name not in q:
        return None
    v = q[name]
    if not (v.isascii() and v.isdigit()) or int(v) > _MAX_INT:
        raise ValidationError("parameter %s must be a whole number of at least 0" % name)
    return int(v)


def qrequired(q, name):
    if name not in q:
        raise ValidationError("missing parameter: %s" % name)
    return q[name]


def build_postings(items, where="postings"):
    from tallybook.model import Posting
    out = []
    for i, p in enumerate(items):
        f = get_fields(p, {"account": ("str", True), "amount": ("money", False), "note": ("str", False)},
                       "%s[%d]." % (where, i))
        amount = to_money(f["amount"]) if "amount" in f else None
        out.append(Posting(f["account"], amount, f.get("note", "")))
    return out


def check_tags(tags):
    if not all(isinstance(t, str) for t in tags):
        raise ValidationError("tags must be a list of text")
    return tuple(tags)


def rate_dict(src, dst, on, text):
    from tallybook.dates import format_date
    return {"src": src, "dst": dst, "date": format_date(on), "rate": text}


def budget_dict(b):
    from tallybook.dates import format_date
    from tallybook.export import money_to_dict
    return {"pattern": b.pattern, "period_kind": b.period_kind, "amount": money_to_dict(b.amount),
            "start": format_date(b.start)}


def recurring_dict(rec):
    from tallybook.dates import format_date
    from tallybook.export import posting_to_dict
    t = rec.template
    return {"name": rec.name, "schedule": str(rec.schedule), "start": format_date(rec.start),
            "end": None if rec.end is None else format_date(rec.end), "count": rec.count,
            "template": {"payee": t.payee, "narration": t.narration, "flag": t.flag, "tags": sorted(set(t.tags)),
                         "postings": [posting_to_dict(p) for p in t.postings]}}


def account_dict(a):
    from tallybook.dates import format_date
    return {"path": a.path, "type": a.type, "currency": a.currency,
            "opened": None if a.opened is None else format_date(a.opened),
            "closed": None if a.closed is None else format_date(a.closed), "note": a.note}


# -- the application ---------------------------------------------------------------

class App:
    def __init__(self, db_path, today=None):
        self.db_path = db_path
        self._today = today

    @property
    def today(self):
        return self._today if self._today is not None else date.today()

    def open(self):
        from tallybook.storage import Store
        return Store.open(self.db_path)

    def handle(self, name, params, method, q, body, ctype, raw):
        """Return (status, payload, content_type) where payload is a JSON value or text."""
        from tallybook.export import transaction_to_dict as txd
        with self.open() as s:
            if name == "health":
                return 200, {"status": "ok", "version": __version__, "schema_version": s.version}, None
            if name == "accounts":
                if method == "GET":
                    accts = s.accounts(type=q.get("type"), under=q.get("under"), currency=q.get("currency"),
                                       include_closed=qbool(q, "include_closed", True))
                    return 200, [account_dict(a) for a in accts], None
                f = get_fields(body, {"path": ("str", True), "type": ("str", False), "currency": ("str", False),
                                      "opened": ("str", False), "note": ("str", False)})
                opened = to_date(f["opened"]) if "opened" in f else None
                a = s.add_account(f["path"], f.get("type"), f.get("currency"), opened, f.get("note", ""))
                return 201, account_dict(a), None
            if name == "account":
                return 200, account_dict(s.get_account(params["path"])), None
            if name == "close":
                f = get_fields(body, {"on": ("str", False)})
                s.get_account(params["path"])
                on = to_date(f["on"]) if "on" in f else self.today
                return 200, account_dict(s.close_account(params["path"], on)), None
            if name == "transactions":
                if method == "GET":
                    limit = qint(q, "limit")
                    offset = qint(q, "offset")
                    offset = 0 if offset is None else offset
                    query = q.get("q")
                    total = s.count_transactions(query)
                    items = s.transactions(query, limit, offset)
                    return 200, {"items": [txd(t) for t in items], "total": total, "limit": limit,
                                 "offset": offset}, None
                from tallybook.model import Transaction
                f = get_fields(body, {"date": ("str", True), "payee": ("str", True), "narration": ("str", False),
                                      "flag": ("str", False), "tags": ("list", False), "postings": ("list", True)})
                tx = Transaction(to_date(f["date"]), f["payee"], f.get("narration", ""),
                                 build_postings(f["postings"]), check_tags(f.get("tags", [])), f.get("flag", "*"))
                return 201, txd(s.add_transaction(tx)), None
            if name == "transaction":
                if method == "GET":
                    return 200, txd(s.get_transaction(params["id"])), None
                return 200, txd(s.delete_transaction(params["id"])), None
            if name == "rates":
                if method == "GET":
                    return 200, [rate_dict(*r) for r in s.rate_rows()], None
                if method == "PUT":
                    f = get_fields(body, {"src": ("str", True), "dst": ("str", True), "date": ("str", True),
                                          "rate": ("str", True)})
                    on = to_date(f["date"])
                    s.set_rate(f["src"], f["dst"], f["rate"], on)
                    return 200, rate_dict(f["src"], f["dst"], on, f["rate"]), None
                src, dst, d = qrequired(q, "src"), qrequired(q, "dst"), qrequired(q, "date")
                on = to_date(d)
                for r in s.rate_rows():
                    if r[0] == src and r[1] == dst and r[2] == on:
                        s.remove_rate(src, dst, on)
                        return 200, rate_dict(*r), None
                s.remove_rate(src, dst, on)
            if name == "budgets":
                if method == "GET":
                    return 200, [budget_dict(b) for b in s.budgets()], None
                if method == "POST":
                    from tallybook.budgets import Budget
                    f = get_fields(body, {"pattern": ("any", True), "period_kind": ("any", True),
                                          "amount": ("money", True), "start": ("str", True)})
                    b = Budget(f["pattern"], f["period_kind"], to_money(f["amount"]), to_date(f["start"]))
                    s.add_budget(b)
                    return 201, budget_dict(b), None
                pattern, kind = qrequired(q, "pattern"), qrequired(q, "period_kind")
                return 200, budget_dict(s.remove_budget(pattern, kind)), None
            if name == "budget_status":
                from tallybook.budgets import budget_status
                from tallybook.dates import Period
                period = Period.parse(qrequired(q, "period"))
                return 200, [l.to_dict() for l in budget_status(s.budgets(), s.ledger(), period)], None
            if name == "recurring":
                if method == "GET":
                    return 200, [recurring_dict(r) for r in s.recurring()], None
                if method == "POST":
                    from tallybook.model import Transaction
                    from tallybook.recurring import Recurring
                    f = get_fields(body, {"name": ("any", True), "schedule": ("any", True), "start": ("str", True),
                                          "template": ("obj", True), "end": ("str", False), "count": ("any", False)})
                    t = get_fields(f["template"], {"payee": ("str", True), "postings": ("list", True),
                                                   "narration": ("str", False), "flag": ("str", False),
                                                   "tags": ("list", False)}, "template.")
                    start = to_date(f["start"])
                    end = to_date(f["end"]) if "end" in f else None
                    template = Transaction(start, t["payee"], t.get("narration", ""),
                                           build_postings(t["postings"], "template.postings"),
                                           check_tags(t.get("tags", [])), t.get("flag", "*"))
                    rec = Recurring(f["name"], f["schedule"], template, start, end, f.get("count"))
                    s.add_recurring(rec)
                    return 201, recurring_dict(rec), None
                return 200, recurring_dict(s.remove_recurring(qrequired(q, "name"))), None
            if name == "materialize":
                f = get_fields(body, {"upto": ("str", False)})
                upto = to_date(f["upto"]) if "upto" in f else None
                made = s.materialize(upto=upto, today=self.today)
                return 200, {"added": [txd(t) for t in made]}, None
            if name == "rules":
                if method == "PUT":
                    f = get_fields(body, {"rules": ("str", True)})
                    s.set_rules(f["rules"])
                return 200, {"rules": s.rules_text()}, None
            if name == "export":
                fmt = q.get("format", "json")
                from tallybook.export import transactions_to_csv
                from tallybook.journal import format_journal
                if fmt == "json":
