class _Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def handle_error(self, request, client_address):
        pass


def serve(db_path, host="127.0.0.1", port=0, today=None):
    from tallybook.storage import LATEST_VERSION, Store
    import os

    if not os.path.exists(os.fspath(db_path)):
        from tallybook.errors import NotFoundError
        raise NotFoundError("no such database: %s (run `tallybook init`)" % os.fspath(db_path))
    with Store.open(db_path) as s:
        v = s.version
        if v < LATEST_VERSION:
            from tallybook.errors import ConflictError
            raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)

    handler = type("BoundHandler", (Handler,), {"app": App(db_path, today)})
    server = _Server((host, port), handler)
    real_port = server.server_address[1]
    sys.stdout.write("tallybook listening on http://%s:%d\n" % (host, real_port))
    sys.stdout.flush()

    stop = threading.Event()
    in_main = threading.current_thread() is threading.main_thread()
    if in_main:
        old = {}

        def on_signal(signum, frame):
            stop.set()

        for sig in (signal.SIGINT, signal.SIGTERM):
            try:
                old[sig] = signal.signal(sig, on_signal)
            except (ValueError, OSError):
                pass
        worker = threading.Thread(target=server.serve_forever, kwargs={"poll_interval": 0.2}, daemon=True)
        worker.start()
        try:
            while not stop.is_set():
                stop.wait(0.5)
        except KeyboardInterrupt:
            pass
        finally:
            server.shutdown()
            server.server_close()
            for sig, h in old.items():
                try:
                    signal.signal(sig, h)
                except (ValueError, OSError, TypeError):
                    pass
    else:
        try:
            server.serve_forever(poll_interval=0.2)
        finally:
            server.server_close()
    return 0
